import{_ as r,l,o as e,c as n,v as t,p as s,x as i,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"脱敏与令牌化","description":"","frontmatter":{"title":"脱敏与令牌化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/data-masking-tokenization.md","filePath":"cs/data-masking-tokenization.md","lastUpdated":1789023840000}'),c={name:"cs/data-masking-tokenization.md"};function _(E,a,m,P,u,A){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="脱敏与令牌化" tabindex="-1">脱敏与令牌化 <a class="header-anchor" href="#脱敏与令牌化" aria-label="Permalink to &quot;脱敏与令牌化&quot;">​</a></h1><div class="epigraph"><p>脱敏把生产数据变成测试可用的形状；令牌化用随机替代值换掉主键，真值放进保险库。二者减少明文扩散，但不能把弱访问控制补成强。</p><footer>—— 据 NIST 对去标识化的讨论；PCI DSS 对令牌化的实践陈述；对照 GDPR 最小化</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/gdpr-technical">GDPR</a>要最小化。缺口是<strong>工程手段</strong>：掩码、令牌、保险库。本课分工，不把脱敏当 DP。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>测试环境拷生产库。缺口：格式保留 vs 随机令牌、保险库 ACL、不可逆哈希盐（回口令课）。</p><h3 id="可逆" tabindex="-1">可逆 <a class="header-anchor" href="#可逆" aria-label="Permalink to &quot;可逆&quot;">​</a></h3><p>可逆令牌化的保险库是新 TCB，等于又一个密钥管理系统。</p><p><span class="marginnote">PCI DSS 令牌化指南。MPC 下一课让计算不必集中明文。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照静态脱敏与动态。下一课 MPC 应用。</p>',12)),(e(),s(p,null,{default:i(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PII%5B%22%E6%98%8E%E6%96%87%E6%A0%87%E8%AF%86%22%5D%20--%3E%20TOK%5B%22%E4%BB%A4%E7%89%8C%22%5D%0A%20%20TOK%20--%3E%20VAULT%5B%22%E4%BF%9D%E9%99%A9%E5%BA%93%E6%98%A0%E5%B0%84%22%5D%0A%20%20MASK%5B%22%E6%B5%8B%E8%AF%95%E8%84%B1%E6%95%8F%22%5D%20--%3E%20SHAPE%5B%22%E4%BF%9D%E7%95%99%E6%A0%BC%E5%BC%8F%E6%97%A0%E7%9C%9F%E5%80%BC%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>减少持有。MPC 下一课连计算都不集中。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写再识别。MPC 应用下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>法律要最小化；令牌化减少明文副本。</li><li>保险库是新 TCB。</li><li>脱敏不是差分隐私。</li><li>下一课 MPC 应用。</li><li>出处：PCI DSS 令牌化；NIST 去标识化讨论。</li></ul>',8))])}const B=r(c,[["render",_]]);export{f as __pageData,B as default};
